    size: KbqSidepanelSize = KbqSidepanelSize.Medium;

    @ViewChild('template', { static: false }) template: TemplateRef<any>;

    openPanel() {
        this.sidepanelService.open(this.template, {
            position: this.position,
            size: this.size
        });
    }
}

