import {
    afterNextRender,
    ChangeDetectionStrategy,
    Component,
    ElementRef,
    inject,
    TemplateRef,
    viewChild
} from '@angular/core';
import { KbqActionsPanel, KbqActionsPanelRef } from '@koobiq/components/actions-panel';
import { KbqButtonModule } from '@koobiq/components/button';
import { KbqDividerModule } from '@koobiq/components/divider';
import { KbqDropdownModule } from '@koobiq/components/dropdown';
import { KbqIconModule } from '@koobiq/components/icon';
import { KbqOverflowItemsModule } from '@koobiq/components/overflow-items';
import { KbqToastService } from '@koobiq/components/toast';
import { KbqToolTipModule } from '@koobiq/components/tooltip';

type ExampleAction = {
    id: string;
    icon: string;
    divider?: boolean;
};

/**
 * @title Actions panel custom counter
 */
@Component({
    selector: 'actions-panel-custom-counter-example',
    imports: [
        KbqOverflowItemsModule,
        KbqButtonModule,
        KbqIconModule,
        KbqDropdownModule,
        KbqDividerModule,
        KbqToolTipModule
    ],
    template: `
        <button kbq-button (click)="open()">open</button>

        <ng-template let-data>
            <div #kbqOverflowItems="kbqOverflowItems" kbqOverflowItems>
                <div order="99" [kbqOverflowItem]="action.Counter">
                    <div class="example-counter">
                        <div class="kbq-text-normal-medium">Selected: {{ data.selected }}</div>
                        <span
                            aria-label="Total number of items in selected groups: +{{ data.counter }}"
                            class="example-counter-extra kbq-text-normal"
                            kbqTooltip="Total number of items in selected groups"
                            tabindex="0"
                            [kbqTooltipOffset]="22"
                        >
                            +{{ data.counter }}
                        </span>
                    </div>
                    <kbq-divider class="example-divider-vertical" [vertical]="true" />
                </div>

                @for (action of actions; track action.id) {
                    <div [kbqOverflowItem]="action.id">
                        @if (action.divider) {
                            <kbq-divider class="example-divider-vertical" [vertical]="true" />
                        }
                        <button
                            color="contrast"
                            kbq-button
                            [class.layout-margin-left-xxs]="!$first"
                            (click)="onAction(action)"
                        >
                            <i [kbq-icon]="action.icon"></i>
                            {{ action.id }}
                        </button>
                    </div>
                }
            </div>

            @let hiddenItemIDs = kbqOverflowItems.hiddenItemIDs();
            <!-- ignores when only action.Counter is hidden -->
            @if (hiddenItemIDs.size > 1) {
                <button
                    kbqOverflowItemsResult
                    color="contrast"
                    kbq-button
                    aria-label="More"
                    [kbqDropdownTriggerFor]="dropdown"
                >
                    <i kbq-icon="kbq-ellipsis-vertical_16"></i>
                </button>
            }

            <kbq-dropdown #dropdown="kbqDropdown">
                <div class="example-counter-dropdown">
                    <div>Selected: {{ data.selected }}</div>
                    <span
                        aria-label="Total number of items in selected groups: +{{ data.counter }}"
                        class="example-counter-extra kbq-text-normal"
                        kbqTooltip="Total number of items in selected groups"
                        tabindex="0"
                        [kbqTooltipOffset]="22"
                    >
                        +{{ data.counter }}
                    </span>
                </div>
                <kbq-divider />

                @for (action of actions; track action.id) {
                    @if (hiddenItemIDs.has(action.id)) {
                        @if (action.divider && hiddenItemIDs.has(actions[$index - 1].id)) {
                            <kbq-divider />
                        }
                        <button kbq-dropdown-item (click)="onAction(action)">
                            <i [kbq-icon]="action.icon"></i>
                            {{ action.id }}
                        </button>
                    }
                }
            </kbq-dropdown>
        </ng-template>
    `,
    styles: `
        :host {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 64px;
            overflow: hidden;
        }

        .example-counter {
            margin: 0 var(--kbq-size-m);
        }

        .example-counter-extra {
            margin-left: var(--kbq-size-xxs);
            outline: none;
        }

        .example-counter-extra:focus-visible {
            outline: 2px solid var(--kbq-states-line-focus-theme);
        }

        .example-counter > .example-counter-extra {
            color: var(--kbq-foreground-on-contrast-secondary);
        }

        .example-counter,
        .example-counter-dropdown {
            display: flex;
            align-items: center;
            user-select: none;
            white-space: nowrap;
        }

        .example-counter-dropdown {
            font-weight: var(--kbq-typography-text-normal-strong-font-weight);
            margin: var(--kbq-size-s) var(--kbq-size-m);
        }

        .kbq-overflow-item {
            display: flex;
            align-items: center;
        }

        .example-divider-vertical {
            background-color: var(--kbq-actions-panel-vertical-divider-background-color);
            height: var(--kbq-actions-panel-vertical-divider-height) !important;
            margin: var(--kbq-actions-panel-vertical-divider-margin);
