    imports: [
        KbqButtonModule,
        KbqPopoverModule,
        KbqInputModule,
        KbqDividerModule,
        FormsModule,
        KbqTextareaModule,
        ReactiveFormsModule,
        KbqTitleModule,
        KbqPipeState,
        KbqPipeButton
    ],
    template: `
        <button
            kbq-button
            kbqPopover
            [disabled]="data.disabled"
            [kbqPipeState]="data"
            [kbq-title]="pipeTooltip"
            [kbqPopoverArrow]="false"
            [kbqPopoverClass]="'kbq-pipe__popover'"
            [kbqPopoverContent]="content"
            [kbqPopoverOffset]="4"
            [kbqPopoverPlacement]="placements.BottomLeft"
            [class]="{ 'kbq-active': popover?.isOpen }"
        >
            <span #kbqTitleText class="kbq-pipe__name">{{ data.name }}</span>
            <span #kbqTitleText class="kbq-pipe__value" [class.kbq-pipe__value_empty]="!data.value">
                {{ data.value }}
            </span>
        </button>

        @if (showRemoveButton) {
            <kbq-pipe-button />
        }

        <ng-template #content>
            <input
                class="layout-margin-bottom-s"
                type="color"
                style="width:100%;"
                [formControl]="control"
                (keydown.enter)="popover.hide()"
            />
        </ng-template>

        <ng-template #pipeTooltip>
            <div class="kbq-pipe-tooltip__name kbq-text-compact">{{ data.name }}</div>
            <div class="kbq-pipe-tooltip__value kbq-text-compact">{{ data.value }}</div>
        </ng-template>
    `,
    styleUrls: ['../../../../components/filter-bar/pipes/base-pipe.scss'],
    providers: [
        {
            provide: KbqBasePipe,
            useExisting: this
        }
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None
})
export class ColorPipeComponent extends KbqBasePipe<string | null> implements AfterViewInit, OnInit {
    readonly placements = PopUpPlacements;

    @ViewChild(KbqPopoverTrigger) popover: KbqPopoverTrigger;

    get isEmpty(): boolean {
        return this.data.value === null || this.data.value === undefined;
    }

    get showRemoveButton(): boolean {
        return !!(!this.data.required && (this.data.removable || (this.data.cleanable && !this.isEmpty)));
    }

    get disabled(): boolean {
        return !this.control.value;
    }

    control = new FormControl<typeof this.data.value>('');

    ngOnInit(): void {
        this.control.setValue(this.data.value);
    }

    ngAfterViewInit() {
        super.ngAfterViewInit();

        this.popover.visibleChange.pipe(takeUntilDestroyed(this.destroyRef)).subscribe((visible) => {
            if (!visible) {
                this.data.value = this.control.value;
                this.filterBar?.onChangePipe.emit(this.data);
            }

            this.stateChanges.next();
        });
    }

    override open() {
        this.popover?.show();
    }
}

