@use '../../core/styles/common';
@use '../filter-bar-theme' as *;

.kbq-pipe {
    display: flex;
    flex-direction: row;

    // Caps the whole pipe, clear and remove buttons included. The label's grid tracks have no
    // min-content, so the trigger gives way down to its own paddings without `min-width: 0`.
    max-width: var(--kbq-filter-bar-pipe-max-width, 320px);
    max-height: 32px;

    & .kbq-select .kbq-select__trigger {
        height: unset;
    }

    // The button's default slot is an inline text box; a pipe puts its own row of two independently
    // truncated parts (name + value) in there, as two shrinkable tracks: as flex items they would give
    // up the same percentage, which wipes out a short name long before a long value becomes unreadable.
    // Qualified with `.kbq-button` on purpose: the base rule is `.kbq-button .kbq-button-text`, so a
    // two-class selector would only win on source order, which differs between app bundles.
    .kbq-button .kbq-button-text {
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: minmax(0, max-content);
        align-items: center;
    }

    .kbq-pipe__name {
        @include common.kbq-truncate-line();
    }

    .kbq-pipe__value {
        @include common.kbq-truncate-line();

        &:not(.kbq-pipe__value_empty) {
            margin-inline-start: 4px;
        }
    }

    .kbq-select:not(:hover, .kbq-active),
    .kbq-tree-select:not(:hover, .kbq-active),
    .kbq-button:not(:hover, .kbq-active, [disabled]) {
        & + .kbq-pipe-button:not(:hover, .kbq-active)::after {
            content: '';
            position: absolute;
            inset-inline-start: 0;
            top: var(--kbq-size-s);

            width: 1px;
            height: var(--kbq-size-l);
        }
    }

    .kbq-button.cdk-keyboard-focused {
        z-index: 1;
    }
}

.kbq-pipe.kbq-pipe_removable,
.kbq-pipe.kbq-pipe_cleanable:not(.kbq-pipe_empty) {
    .kbq-button {
        border-end-end-radius: unset;
