    protected pipeTemplates: KbqPipeTemplate[] = [
        {
            name: 'Select',
            type: KbqPipeTypes.Select,
            values: SELECT_VALUES,
            cleanable: true,
            removable: true,
            disabled: false
        },
        {
            name: 'Text',
            type: KbqPipeTypes.Text,
            cleanable: true,
            removable: true,
            disabled: false
        }
    ];
}

