inline-edit-save-error.inline-edit-save-error-example.ts:
import { ChangeDetectionStrategy, Component, forwardRef, inject, TemplateRef, viewChild } from '@angular/core';
import { FormControl, ReactiveFormsModule, Validators } from '@angular/forms';
import { KbqButtonModule } from '@koobiq/components/button';
import { KbqIconModule } from '@koobiq/components/icon';
import {
    KBQ_INLINE_EDIT_SAVE_ERROR_HANDLER,
    KbqInlineEdit,
    KbqInlineEditMode,
    KbqInlineEditModule,
    KbqInlineEditSaveErrorContext,
    KbqInlineEditSaveHandler
} from '@koobiq/components/inline-edit';
import { KbqInputModule } from '@koobiq/components/input';
import { KbqLinkModule } from '@koobiq/components/link';
import { KbqToastComponent, KbqToastModule, KbqToastService, KbqToastStyle } from '@koobiq/components/toast';
import { Observable, of, switchMap, throwError, timer } from 'rxjs';

const TAKEN_NAMES = ['Admins', 'Support'];

class ExampleSaveError extends Error {
    constructor(
        /** Name of the field the message is about. */
        readonly field: string,
        message: string,
        /** Whether the server rejected the value itself, as opposed to failing for another reason. */
        readonly invalidValue: boolean
    ) {
        super(message);
    }
}

/**
 * @title Inline edit save error
 */
@Component({
    selector: 'inline-edit-save-error-example',
    imports: [
        ReactiveFormsModule,
        KbqInlineEditModule,
        KbqInputModule,
        KbqButtonModule,
        KbqIconModule,
        KbqLinkModule,
        KbqToastModule
    ],
    template: `
        <p class="example-intro layout-margin-top-none layout-margin-bottom-l">
            Save
            <span class="kbq-text-normal-strong">{{ takenNames }}</span>
            as the name to have the value rejected. Saving the description fails on the first attempt and succeeds on
            retry.
        </p>

        <kbq-inline-edit #nameEdit showActions [saveHandler]="saveName" (modeChange)="onModeChange($event, nameEdit)">
            <kbq-label>Name</kbq-label>

            <div class="example-inline-text" kbqInlineEditViewMode>{{ nameControl.value }}</div>
            <kbq-form-field kbqInlineEditEditMode>
                <input kbqInput [formControl]="nameControl" />
            </kbq-form-field>
        </kbq-inline-edit>

        <kbq-inline-edit
            #descriptionEdit
            showActions
            [saveHandler]="saveDescription"
            (modeChange)="onModeChange($event, descriptionEdit)"
        >
            <kbq-label>Description</kbq-label>

            <div class="example-inline-text" kbqInlineEditViewMode>{{ descriptionControl.value }}</div>
            <kbq-form-field kbqInlineEditEditMode>
                <input kbqInput [formControl]="descriptionControl" />
            </kbq-form-field>
        </kbq-inline-edit>

        <ng-template #nameTitle>
            Couldn’t update the field
            <span class="kbq-text-normal-strong">Name</span>
        </ng-template>

        <ng-template #descriptionTitle>
            Couldn’t update the field
            <span class="kbq-text-normal-strong">Description</span>
        </ng-template>

        <!-- The failure is not about the value, so the same value is worth sending again. -->
        <ng-template #retryActions let-toast>
            <a
                kbq-link
                pseudo
                role="button"
                (click)="retry(toast)"
                (keydown.enter)="retry(toast)"
                (keydown.space)="$event.preventDefault(); retry(toast)"
            >
                Retry
            </a>
        </ng-template>

        <!-- The server rejected the value, so the user either fixes it or drops it. -->
        <ng-template #rejectedActions let-toast>
            <a
                kbq-link
                pseudo
                role="button"
                class="layout-margin-right-m"
                (click)="edit(toast)"
                (keydown.enter)="edit(toast)"
                (keydown.space)="$event.preventDefault(); edit(toast)"
            >
                Edit
            </a>
            <a
                kbq-link
                pseudo
                role="button"
                (click)="discard(toast)"
                (keydown.enter)="discard(toast)"
                (keydown.space)="$event.preventDefault(); discard(toast)"
            >
                Discard changes
            </a>
        </ng-template>

        <!-- Closing the notification without reacting discards the unsaved value as well. -->
        <ng-template #closeButton let-toast>
            <button
                type="button"
                kbq-toast-close-button
                kbq-icon-button="kbq-xmark-s_16"
                aria-label="Close"
                (click)="discard(toast)"
            ></button>
        </ng-template>
    `,
    styles: `
        /* Lines the text up with the inline edit content, which its own horizontal padding indents. */
        .example-intro {
            padding-inline: var(--kbq-size-s);
        }

        .example-inline-text {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
    `,
    providers: [
        {
            provide: KBQ_INLINE_EDIT_SAVE_ERROR_HANDLER,
            // The inline edits resolve the token while this component is already constructed, so it can hand out
            // its own method as the application-wide reaction to a failed save.
            useFactory:
                (example: InlineEditSaveErrorExample) => (context: KbqInlineEditSaveErrorContext<ExampleSaveError>) =>
                    example.showSaveErrorToast(context),
            deps: [forwardRef(() => InlineEditSaveErrorExample)]
        }
    ],
    changeDetection: ChangeDetectionStrategy.OnPush,
    host: {
        class: 'layout-flex layout-column'
    }
})
export class InlineEditSaveErrorExample {
    protected readonly takenNames = TAKEN_NAMES.join(', ');

    protected readonly nameControl = new FormControl('Security team', {
        nonNullable: true,
        validators: [Validators.required]
    });
    protected readonly descriptionControl = new FormControl('Monitors incidents', { nonNullable: true });

    protected readonly saveName: KbqInlineEditSaveHandler = () => this.saveNameOnServer(this.nameControl.value);
    protected readonly saveDescription: KbqInlineEditSaveHandler = () => this.saveDescriptionOnServer();

    private readonly toastService = inject(KbqToastService);
    private readonly nameTitle = viewChild.required<TemplateRef<unknown>>('nameTitle');
    private readonly descriptionTitle = viewChild.required<TemplateRef<unknown>>('descriptionTitle');
    private readonly retryActions = viewChild.required<TemplateRef<unknown>>('retryActions');
    private readonly rejectedActions = viewChild.required<TemplateRef<unknown>>('rejectedActions');
    private readonly closeButton = viewChild.required<TemplateRef<unknown>>('closeButton');

    /** Inline edit behind every open notification, so its buttons act on the field the notification is about. */
    private readonly failedSaves = new Map<number, KbqInlineEditSaveErrorContext<ExampleSaveError>>();
    private descriptionAttempts = 0;

    /** Reports a failed save the way the application does it — here, with a toast the user has to answer. */
    showSaveErrorToast(context: KbqInlineEditSaveErrorContext<ExampleSaveError>): void {
        const { error } = context;

        const { id } = this.toastService.show(
            {
                style: KbqToastStyle.Error,
                title: error.field === 'Name' ? this.nameTitle() : this.descriptionTitle(),
                caption: error.message,
                actions: error.invalidValue ? this.rejectedActions() : this.retryActions(),
                closeButton: this.closeButton()
            },
            // The notification carries the only way back, so it never hides on its own.
            0
        );

        this.failedSaves.set(id, context);
    }

    /** A field opened for editing again makes its notification pointless: it is about the value being changed. */
    protected onModeChange(mode: KbqInlineEditMode, inlineEdit: KbqInlineEdit): void {
        if (mode !== 'edit') return;

        for (const [id, context] of this.failedSaves) {
            if (context.inlineEdit === inlineEdit) {
                this.toastService.hide(id);
                this.failedSaves.delete(id);
            }
        }
    }

    protected retry(toast: KbqToastComponent): void {
        this.take(toast)?.inlineEdit.retrySave();
        toast.close();
    }

    protected edit(toast: KbqToastComponent): void {
        this.take(toast)?.inlineEdit.toggleMode();
        toast.close();
    }

    protected discard(toast: KbqToastComponent): void {
        this.take(toast)?.inlineEdit.rollback();
        toast.close();
    }

    private take(toast: KbqToastComponent): KbqInlineEditSaveErrorContext<ExampleSaveError> | undefined {
        const context = this.failedSaves.get(toast.id);

        this.failedSaves.delete(toast.id);

        return context;
    }

    // The methods below emulate requests; in a real project return the HttpClient observable.
    private saveNameOnServer(value: string): Observable<unknown> {
        return timer(1000).pipe(
            switchMap(() =>
                TAKEN_NAMES.includes(value.trim())
                    ? throwError(() => new ExampleSaveError('Name', `The name «${value}» is already taken`, true))
                    : of(value)
            )
        );
    }

    private saveDescriptionOnServer(): Observable<unknown> {
        const attempt = ++this.descriptionAttempts;

        return timer(1000).pipe(
            switchMap(() =>
                attempt % 2 === 1
                    ? throwError(
                          () => new ExampleSaveError('Description', 'The server is not responding. Try again', false)
                      )
                    : of(null)
            )
        );
    }
}

inline-edit-save-invalid-items.inline-edit-save-invalid-items-example.t:
import { ChangeDetectionStrategy, Component, inject, signal, TemplateRef, viewChild } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { KbqBadgeColors, KbqBadgeModule } from '@koobiq/components/badge';
import { KbqButtonModule } from '@koobiq/components/button';
import { KbqComponentColors } from '@koobiq/components/core';
import { KbqIconModule } from '@koobiq/components/icon';
import {
    KbqInlineEditMode,
    KbqInlineEditModule,
    KbqInlineEditSaveErrorContext,
    KbqInlineEditSaveHandler
} from '@koobiq/components/inline-edit';
import { KbqLinkModule } from '@koobiq/components/link';
import { KbqSelectModule } from '@koobiq/components/select';
import { KbqTagsModule } from '@koobiq/components/tags';
import { KbqToastComponent, KbqToastModule, KbqToastService, KbqToastStyle } from '@koobiq/components/toast';
import { Observable, of, switchMap, throwError, timer } from 'rxjs';

const ROLES = ['user:read', 'user:create', 'user:update', 'user:delete', 'audit:read'];
/** Roles the fake server refuses to grant. */
const FORBIDDEN_ROLES = ['user:delete', 'user:update'];

class ExampleRolesError extends Error {
    constructor(readonly rejectedRoles: string[]) {
        super(`These roles are not available: ${rejectedRoles.join(', ')}`);
    }
}

/**
 * @title Inline edit save invalid items
 */
@Component({
    selector: 'inline-edit-save-invalid-items-example',
    imports: [
        ReactiveFormsModule,
        KbqInlineEditModule,
        KbqSelectModule,
        KbqBadgeModule,
        KbqButtonModule,
        KbqIconModule,
        KbqLinkModule,
        KbqTagsModule,
        KbqToastModule
    ],
    template: `
        <p class="example-intro layout-margin-top-none layout-margin-bottom-l">
            Add
            <span class="kbq-text-normal-strong">{{ forbiddenRoles }}</span>
            to the roles to have the server reject them.
        </p>

        <kbq-inline-edit
            showActions
            [saveHandler]="save"
            (saved)="rejectedRoles.set([])"
            (saveError)="showToast($event)"
            (modeChange)="onModeChange($event)"
        >
            <kbq-label>Roles</kbq-label>

            <div class="layout-row layout-gap-xxs" style="flex-wrap: wrap;" kbqInlineEditViewMode>
                @for (role of control.value; track role) {
                    <!-- The server reports which values it refused, so only those badges turn into the error state. -->
                    <kbq-badge
                        [badgeColor]="rejectedRoles().includes(role) ? badgeColors.Error : badgeColors.FadeContrast"
                    >
                        {{ role }}
                    </kbq-badge>
                } @empty {
                    <span kbqInlineEditPlaceholder>{{ placeholder }}</span>
                }
            </div>

            <kbq-form-field kbqInlineEditEditMode>
                <kbq-select multiple [placeholder]="placeholder" [formControl]="control">
                    @for (role of roles; track role) {
                        <kbq-option [value]="role">{{ role }}</kbq-option>
                    }

                    <!-- The tags carry the same marks as the badges, so the refused role is visible while editing. -->
                    <ng-template #kbqSelectTagContent let-option let-select="select">
                        <kbq-tag
                            [selectable]="false"
                            [disabled]="option.disabled || select.disabled"
                            [color]="rejectedRoles().includes(option.value) ? tagColors.Error : tagColors.ContrastFade"
                        >
                            {{ option.viewValue }}
                            <!-- The custom template replaces the built-in markup, so the remove control is up to us. -->
                            @if (!option.disabled && !select.disabled) {
                                <i
                                    kbq-icon="kbq-xmark-s_16"
                                    kbqTagRemove
                                    (click)="select.onRemoveMatcherItem(option, $event)"
                                ></i>
                            }
                        </kbq-tag>
                    </ng-template>
                </kbq-select>
            </kbq-form-field>
        </kbq-inline-edit>

        <ng-template #title>
            Couldn’t update the field
            <span class="kbq-text-normal-strong">Roles</span>
        </ng-template>

        <ng-template #actions let-toast>
            <a
                kbq-link
                pseudo
                role="button"
                class="layout-margin-right-m"
                (click)="edit(toast)"
                (keydown.enter)="edit(toast)"
                (keydown.space)="$event.preventDefault(); edit(toast)"
            >
                Edit
            </a>
            <a
                kbq-link
                pseudo
                role="button"
                (click)="discard(toast)"
                (keydown.enter)="discard(toast)"
                (keydown.space)="$event.preventDefault(); discard(toast)"
            >
                Discard changes
            </a>
        </ng-template>

        <!-- Closing the notification without reacting discards the unsaved value as well. -->
        <ng-template #closeButton let-toast>
            <button
                type="button"
                kbq-toast-close-button
                kbq-icon-button="kbq-xmark-s_16"
                aria-label="Close"
                (click)="discard(toast)"
            ></button>
        </ng-template>
    `,
    styles: `
        /* Lines the text up with the inline edit content, which its own horizontal padding indents. */
        .example-intro {
            padding-inline: var(--kbq-size-s);
        }
    `,
    changeDetection: ChangeDetectionStrategy.OnPush,
    host: {
        class: 'layout-flex layout-column'
    }
})
export class InlineEditSaveInvalidItemsExample {
    protected readonly placeholder = 'Placeholder';
    protected readonly roles = ROLES;
    protected readonly badgeColors = KbqBadgeColors;
    protected readonly tagColors = KbqComponentColors;

    protected readonly forbiddenRoles = FORBIDDEN_ROLES.join(', ');

    protected readonly control = new FormControl<string[]>(['user:read', 'user:create'], { nonNullable: true });
    /** Values of the last failed save the server refused, matched against the badges in view mode. */
    protected readonly rejectedRoles = signal<string[]>([]);

    protected readonly save: KbqInlineEditSaveHandler = () => this.saveOnServer(this.control.value);

    private readonly toastService = inject(KbqToastService);
    private readonly title = viewChild.required<TemplateRef<unknown>>('title');
    private readonly actions = viewChild.required<TemplateRef<unknown>>('actions');
    private readonly closeButton = viewChild.required<TemplateRef<unknown>>('closeButton');
    private failedSave: KbqInlineEditSaveErrorContext<ExampleRolesError> | null = null;
    private toastId: number | null = null;

    constructor() {
        // Editing the value drops the marks: they belong to the values that were sent.
        this.control.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.rejectedRoles.set([]));
    }

    protected showToast(context: KbqInlineEditSaveErrorContext<ExampleRolesError>): void {
        const { error } = context;

        this.rejectedRoles.set(error.rejectedRoles);
        this.failedSave = context;

        const { id } = this.toastService.show(
            {
                style: KbqToastStyle.Error,
                title: this.title(),
                caption: error.message,
                actions: this.actions(),
                closeButton: this.closeButton()
            },
            0
        );

        this.toastId = id;
    }

    /** The field is being edited again, so the notification about the previous attempt has nothing left to say. */
    protected onModeChange(mode: KbqInlineEditMode): void {
        if (mode === 'edit') {
            this.hideToast();
        }
    }

    protected edit(toast: KbqToastComponent): void {
        this.failedSave?.inlineEdit.toggleMode();
        toast.close();
        this.toastId = null;
    }

    protected discard(toast: KbqToastComponent): void {
        this.failedSave?.inlineEdit.rollback();
        toast.close();
        this.toastId = null;
    }

    private hideToast(): void {
        if (this.toastId === null) return;

        this.toastService.hide(this.toastId);
        this.toastId = null;
    }

    // Emulates a request; in a real project return the HttpClient observable.
    private saveOnServer(value: string[]): Observable<unknown> {
        const rejected = value.filter((role) => FORBIDDEN_ROLES.includes(role));

        return timer(1000).pipe(
            switchMap(() => (rejected.length ? throwError(() => new ExampleRolesError(rejected)) : of(value)))
        );
    }
}

