import { moveItemInArray } from '@angular/cdk/drag-drop';
import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { KbqDividerModule } from '@koobiq/components/divider';
import { KbqListModule, KbqListSelectionDroppedEvent } from '@koobiq/components/list';

/**
 * @title Draggable list
 */
@Component({
    selector: 'list-draggable-example',
    imports: [KbqListModule, KbqDividerModule],
    template: `
        <kbq-list-selection multiple="checkbox" [draggable]="true" (dropped)="dropped($event)">
            @for (item of beforeGroup(); track item.id) {
                <kbq-list-option [value]="item">{{ item.name }}</kbq-list-option>
            }
            <kbq-optgroup label="Group header">
                @for (item of grouped(); track item.id) {
                    <kbq-list-option [value]="item">{{ item.name }}</kbq-list-option>
                }
            </kbq-optgroup>
            <!-- Decorative: a listbox owns options and groups, and a separator has nothing to announce. -->
            <kbq-divider aria-hidden="true" />
            @for (item of afterDivider(); track item.id) {
                <kbq-list-option [draggable]="!item.pinned" [value]="item">{{ item.name }}</kbq-list-option>
            }
        </kbq-list-selection>
    `,
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ListDraggableExample {
    protected readonly items = signal([
        { id: 1, name: 'Item 1' },
        { id: 2, name: 'Item 2' },
        { id: 3, name: 'Item 3' },
        { id: 4, name: 'Item 4' },
        { id: 5, name: 'Item 5' },
        { id: 6, name: 'Item 6' },
        { id: 7, name: 'Item 7. Sorting is prohibited', pinned: true }
    ]);

    // The group and the divider sit at fixed positions, so the sections are plain slices and the indices
    // `dropped` reports address the array directly. An option dragged past a boundary changes section.
    protected readonly beforeGroup = computed(() => this.items().slice(0, 2));
    protected readonly grouped = computed(() => this.items().slice(2, 5));
    protected readonly afterDivider = computed(() => this.items().slice(5));

    protected dropped({ previousIndex, currentIndex }: KbqListSelectionDroppedEvent): void {
        const items = [...this.items()];

        moveItemInArray(items, previousIndex, currentIndex);

        this.items.set(items);
    }
}

list-draggable-connected.list-draggable-connected-example.ts:
import { moveItemInArray, transferArrayItem } from '@angular/cdk/drag-drop';
import { ChangeDetectionStrategy, Component, signal, WritableSignal } from '@angular/core';
import { KbqListModule, KbqListSelectionDroppedEvent } from '@koobiq/components/list';

type Metric = { id: number; name: string };

/**
 * @title Draggable list with transfer between lists
 */
@Component({
    selector: 'list-draggable-connected-example',
    imports: [KbqListModule],
    template: `
        <div class="layout-row layout-gap-l">
            <kbq-list-selection
                #available="kbqListSelection"
                class="flex"
                dragCursor="grab"
                [connectedTo]="[selected]"
                [draggable]="true"
                (dropped)="dropped($event)"
            >
                @for (metric of availableMetrics(); track metric.id) {
                    <kbq-list-option [value]="metric">{{ metric.name }}</kbq-list-option>
                }
            </kbq-list-selection>

            <kbq-list-selection
                #selected="kbqListSelection"
                class="flex"
                dragCursor="grab"
                [connectedTo]="[available]"
                [draggable]="true"
                (dropped)="dropped($event)"
            >
                @for (metric of selectedMetrics(); track metric.id) {
                    <kbq-list-option [value]="metric">{{ metric.name }}</kbq-list-option>
                }
            </kbq-list-selection>
        </div>
    `,
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ListDraggableConnectedExample {
    protected readonly availableMetrics = signal<Metric[]>([
        { id: 1, name: 'CPU load' },
        { id: 2, name: 'Memory usage' },
        { id: 3, name: 'Disk I/O' }
    ]);

    protected readonly selectedMetrics = signal<Metric[]>([{ id: 4, name: 'Network traffic' }]);

    protected dropped({
        previousIndex,
        currentIndex,
        previousContainer,
        container,
        option
    }: KbqListSelectionDroppedEvent): void {
        // `previousContainer` and `container` identify the lists, but only the consumer knows which
        // array backs which list — here the dragged value itself is the lookup key.
        const fromAvailable = this.availableMetrics().includes(option.value);
        const source = fromAvailable ? this.availableMetrics : this.selectedMetrics;

        if (previousContainer === container) {
            this.reorder(source, previousIndex, currentIndex);

            return;
        }

        const target = fromAvailable ? this.selectedMetrics : this.availableMetrics;

        this.transfer(source, target, previousIndex, currentIndex);
    }

    private reorder(list: WritableSignal<Metric[]>, previousIndex: number, currentIndex: number): void {
        const items = [...list()];

        moveItemInArray(items, previousIndex, currentIndex);

        list.set(items);
    }

    private transfer(
        source: WritableSignal<Metric[]>,
        target: WritableSignal<Metric[]>,
        previousIndex: number,
        currentIndex: number
    ): void {
        const from = [...source()];
        const to = [...target()];

        transferArrayItem(from, to, previousIndex, currentIndex);

        source.set(from);
        target.set(to);
    }
}

