                    @for (dashboard of dashboards; track dashboard) {
                        <a kbqTabLink [active]="activeDashboard === dashboard" (click)="activeDashboard = dashboard">
                            {{ dashboard }}
                        </a>
                    }
                </nav>
            </div>

            <div class="example-tabs-actionbar_controls">
                <button class="kbq-button_transparent" color="contrast" kbq-button aria-label="List view">
