                <button class="kbq-button_transparent" color="contrast" kbq-button aria-label="Filter">
                    <i kbq-icon="kbq-filter_16"></i>
                </button>
                <button color="contrast" kbq-button (click)="createDashboard()">
                    <i kbq-icon="kbq-plus_16"></i>
