const getAutocompleteOptions = () => [
    'BruteForce',
    'Complex Attack',
    'DDoS',
    'HIPS alert',
    'Malware',
    'Phishing'
];

/** Tags the user is not allowed to take off. */
const lockedTags = ['DDoS'];

/**
