                    <kbq-tag [value]="tag" [disabled]="isLocked(tag)" (removed)="removedFromKept($event)">
                        {{ tag }}
                        <i kbq-icon-button="kbq-xmark-s_16" kbqTagRemove></i>
                    </kbq-tag>
                }

                <input
                    autocomplete="off"
                    kbqInput
