                                <i kbq-icon="" [class]="action.icon"></i>
                            }
                            @if (canTooltipBeAppied(action)) {
                                {{ action.text }}
                            }
                        </button>
                    }

                    <div kbqOverflowItemsResult>
                        <button
                            kbq-button
                            aria-label="More"
