                        ></i>
                        @if (node.loading) {
                            <kbq-progress-spinner mode="indeterminate" />
                        }
                        {{ treeControl.getViewValue(node) }}
                    </kbq-tree-option>
                </kbq-tree-selection>

                <kbq-cleaner />
            </kbq-tree-select>
        </kbq-form-field>
    `,
